"""Hand-authored expected outcomes, not snapshots generated by selection policy."""

import copy
import json
from dataclasses import replace
from datetime import UTC, datetime, timedelta
from pathlib import Path

import pytest
from amphora_capability_registry.descriptors.assessments import CapacityObservation
from amphora_capability_registry.descriptors.identity import ReleaseConflict, ReleaseDocument
from amphora_capability_registry.descriptors.policy import (
    EligibilityEvaluator,
    EvaluationPolicy,
    PermissionPolicy,
)
from amphora_capability_registry.descriptors.requirements import CapabilityNeed, ResourceAllowance
from amphora_capability_registry.descriptors.validation import DescriptorValidator
from amphora_contracts_core import Scope
from amphora_contracts_tools import LockEntry, ReleaseDescriptor
from export_schemas import ROOT
from jsonschema import Draft202012Validator
from pydantic import ValidationError

BASE = json.loads((ROOT / "contracts/fixtures/v1/tool_releases.json").read_text())[0]
ORACLES = json.loads(Path(__file__).with_name("fixtures").joinpath("failure_oracles.json").read_text())
NOW = datetime(2026, 9, 28, 12, tzinfo=UTC)
SCOPE = Scope(tenant_id="internal", project_id="synthetic")


def descriptor(raw):
    return ReleaseDescriptor.model_validate_json(json.dumps(raw))


def allowance():
    return ResourceAllowance("x86_64", "windows", 2000, 128, 0, 60, 4, 64)


@pytest.mark.parametrize("oracle", ORACLES, ids=lambda value: value["name"])
def test_independent_failure_oracle(oracle):
    raw = copy.deepcopy(BASE["descriptor"])
    if change := oracle.get("change"):
        target = raw
        for part in change["path"][:-1]:
            target = target[part]
        if change.get("delete"):
            del target[change["path"][-1]]
        else:
            target[change["path"][-1]] = change["value"]
    if oracle["stage"] == "wire":
        with pytest.raises(ValidationError) as error:
            descriptor(raw)
        assert any(list(item["loc"]) == oracle["location"] and item["type"] == oracle["error"]
                   for item in error.value.errors())
        assert list(Draft202012Validator(ReleaseDescriptor.model_json_schema()).iter_errors(raw))
        return
    release = descriptor(raw)
    document = ReleaseDocument.from_descriptor(release)
    if oracle["stage"] == "lock":
        with pytest.raises(ReleaseConflict, match=oracle["error"]):
            document.verify_lock(LockEntry.model_validate_json(json.dumps(BASE["lock"])))
        return
    need = CapabilityNeed.for_tool(SCOPE, oracle.get("context", "synthetic-tests"), descriptor(BASE["descriptor"]).tool)
    capacity = CapacityObservation(SCOPE, document.digest, 1, 1, NOW, NOW + timedelta(seconds=30))
    result = EligibilityEvaluator().evaluate(release, need, EvaluationPolicy(SCOPE, allowance(), PermissionPolicy()),
                                              capacity, now=NOW).to_wire()
    assert result.status == "rejected"
    assert result.observations.structural.status == oracle["structural"]
    if "finding" in oracle:
        assert [item.code for item in result.observations.structural.findings] == [oracle["finding"]]
    assert result.observations.scientific.status == oracle["scientific"]
    assert result.observations.scientific.reason_codes == (oracle["science_reason"],)
    assert result.observations.capacity.status == "available"
    assert result.admission.status == oracle["admission"]
    assert list(result.admission.reason_codes) == oracle["reasons"]


@pytest.mark.parametrize("values", [{"architecture": "unknown"}, {"operating_system": "unknown"},
    {"memory_mib": True}, {"memory_mib": 0}, {"cpu_millicores": float("inf")}, {"gpu_count": -1}])
def test_host_allowances_reject_unknown_or_nonfinite_values(values):
    with pytest.raises(ValueError):
        replace(allowance(), **values)


@pytest.mark.parametrize("hosts", [["a.invalid"], ("*",), ("a.invalid", "a.invalid"), ([],), (None,),
                                  ("https://a.invalid",), tuple(f"h{i}.invalid" for i in range(65))])
def test_host_policy_requires_bounded_explicit_names(hosts):
    with pytest.raises(ValueError, match="egress host"):
        PermissionPolicy(hosts)


@pytest.mark.parametrize("fault,reason", [("duplicate", "duplicate_required_port"),
    ("missing", "required_port_missing"), ("unsupplied", "required_input_unsupplied")])
def test_request_port_ambiguity_or_incompleteness_rejects_selection(fault, reason):
    release = descriptor(BASE["descriptor"])
    need = CapabilityNeed.for_tool(SCOPE, "synthetic-tests", release.tool)
    if fault == "duplicate":
        need = replace(need, inputs=need.inputs * 2)
    elif fault == "missing":
        need = replace(need, outputs=(replace(need.outputs[0], name="absent"),))
    else:
        need = replace(need, inputs=())
    result = EligibilityEvaluator().evaluate(release, need, EvaluationPolicy(SCOPE, allowance(), PermissionPolicy()),
                                              None, now=NOW).to_wire()
    assert result.admission.reason_codes == (reason,)
    assert result.status == "rejected"


def test_valid_checkpoint_writer_is_readable_and_diagnostics_are_bounded():
    raw = copy.deepcopy(BASE["descriptor"])
    schema = raw["tool"]["inputs"][0]["schema_ref"]
    raw["tool"]["checkpoint_schema"] = schema
    raw["checkpoint"] = {"mode": "opaque_artifact", "readable_schema_sha256": [schema["sha256"]]}
    assert DescriptorValidator().validate(descriptor(raw)).valid
    for side in ("inputs", "outputs"):
        port = copy.deepcopy(raw["tool"][side][0])
        port["unit"] = " "
        raw["tool"][side] = [port] * 64
    report = DescriptorValidator().validate(descriptor(raw)).to_wire()
    assert report.status == "invalid" and len(report.findings) == 128
